fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
    const MAX_VECTORED_CHUNKS: usize = 64;

    let me = self.project();

    ready!(crate::trace::trace_leaf(cx));
    ready!(poll_proceed_and_make_progress(cx));

    if me.writer.is_write_vectored() {
        loop {
            if !me.buf.has_remaining() {
                return Poll::Ready(Ok(()));
            }

            let mut slices = [IoSlice::new(&[]); MAX_VECTORED_CHUNKS];
            let n = me.buf.chunks_vectored(&mut slices);

            match ready!(Pin::new(&mut *me.writer).poll_write_vectored(cx, &slices[..n])) {
                Ok(0) => return Poll::Ready(Err(io::ErrorKind::WriteZero.into())),
                Ok(n) => me.buf.advance(n),
                Err(e) => return Poll::Ready(Err(e)),
            }
        }
    } else {
        loop {
            if !me.buf.has_remaining() {
                return Poll::Ready(Ok(()));
            }

            match ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())) {
                Ok(0) => return Poll::Ready(Err(io::ErrorKind::WriteZero.into())),
                Ok(n) => me.buf.advance(n),
                Err(e) => return Poll::Ready(Err(e)),
            }
        }
    }
}

